import { execSync } from 'child_process';
import fs from 'fs';
const W='';
const FILES={'assets/pet-profile.js':''};
const TOKG=process.env.GH_TOKEN, REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const U=process.env.WP_USER||'', P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='-u "'+U+':'+P+'"';
function wj(m,path,body){fs.writeFileSync('/tmp/wb.json', JSON.stringify(body));
  return execSync('curl -sk '+AUTH+' -X '+m+' -H "Content-Type: application/json" --data-binary @/tmp/wb.json "https://dev.avesa.lt/wp-json/'+path+'"',{maxBuffer:50e6,timeout:70000}).toString();}
function putB64(name,b64){const u='https://api.github.com/repos/'+REPO+'/contents/screenshots/'+name;let s='';
 for(let i=0;i<5;i++){try{const j=JSON.parse(execSync('curl -s -H "Authorization: Bearer '+TOKG+'" "'+u+'?n='+Math.random()+'"',{maxBuffer:50e6}).toString());if(j.sha)s=j.sha;}catch(e){}
  fs.writeFileSync('/tmp/pj.json',JSON.stringify({message:'r',content:b64,...(s?{sha:s}:{})}));
  const c=execSync('curl -s -o /dev/null -w "%{http_code}" -X PUT -H "Authorization: Bearer '+TOKG+'" -d @/tmp/pj.json "'+u+'"',{maxBuffer:50e6}).toString().trim();
  if(c==='200'||c==='201')return c; execSync('sleep 2');}return 'fail';}
const o={}; const shots=[];
try{
  // 1. Deploy JS
  const mk=wj('POST','code-snippets/v1/snippets',{name:'A2FIX (temp)',code:Buffer.from(W,'base64').toString('utf8'),scope:'front-end',active:true,priority:5});
  let sid=null; try{sid=JSON.parse(mk).id;}catch(e){}
  execSync('sleep 4');
  fs.writeFileSync('/tmp/payload.json', JSON.stringify({files:FILES}));
  for(let a=0;a<4;a++){ try{const r=execSync('curl -sk -X POST -H "Content-Type: application/json" --data-binary @/tmp/payload.json "https://dev.avesa.lt/?ps_dep218=Dp218x"',{maxBuffer:20e6,timeout:90000}).toString();
    const j=r.slice(r.indexOf('{'),r.lastIndexOf('}')+1); o.write=j.slice(0,120); if(j.includes('pet-profile.js'))break; }catch(e){} execSync('sleep 4'); }
  if(sid!==null){ try{wj('POST','code-snippets/v1/snippets/'+sid,{active:false});}catch(e){} try{execSync('curl -sk '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"');}catch(e){} }

  // 2. Ivedu testinius duomenis pet_id=30 per PHP snippet
  const SEED=`<?php
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_seed']) || $_GET['ps_seed']!=='Seed25x') return;
  global $wpdb; $pf=$wpdb->prefix;
  $pid=30;
  $uid=$wpdb->get_var($wpdb->prepare("SELECT user_id FROM {$pf}ps_pets WHERE id=%d",$pid));
  // produktas - imu bet koki instock is katalogo
  $prod=$wpdb->get_var("SELECT p.ID FROM {$pf}posts p WHERE p.post_type='product' AND p.post_status='publish' LIMIT 1");
  // 2a. primary_product meta (busena B)
  $wpdb->update("{$pf}ps_pets", array(
    'primary_product_id'=>$prod,
    'primary_product_name'=>'Royal Canin Sterilised (TEST)',
    'primary_product_package'=>'2 kg'
  ), array('id'=>$pid));
  // 2b. priminimas (Kas svarbu dabar)
  $wpdb->query("DELETE FROM {$pf}ps_reminders WHERE pet_id=$pid AND reminder_label LIKE '%TEST%'");
  $wpdb->insert("{$pf}ps_reminders", array(
    'user_id'=>$uid,'pet_id'=>$pid,'reminder_type'=>'flea_tick',
    'reminder_label'=>'Apsauga nuo erkiu (TEST)','due_date'=>date('Y-m-d', time()+5*86400),
    'notify_email'=>1,'created_at'=>current_time('mysql')
  ));
  // 2c. refill likutis (busena C) - jei lentele yra
  $rt=$pf.'ps_refill_tracking';
  if($wpdb->get_var("SHOW TABLES LIKE '$rt'")){
    $wpdb->query("DELETE FROM $rt WHERE pet_id=$pid");
    $wpdb->insert($rt, array(
      'user_id'=>$uid,'pet_id'=>$pid,'product_id'=>$prod,
      'predicted_empty_date'=>date('Y-m-d', time()+9*86400),
      'avg_interval_days'=>30,'purchase_count'=>3,'confidence'=>0.8,
      'last_purchase_date'=>date('Y-m-d', time()-21*86400),'status'=>'active'
    ));
  }
  header('Content-Type: application/json');
  echo '###SEED###'.json_encode(array('pid'=>$pid,'uid'=>$uid,'prod'=>$prod,'rt_exists'=>!!$wpdb->get_var("SHOW TABLES LIKE '$rt'"))).'###END###';
  exit;
});`;
  const mk2=wj('POST','code-snippets/v1/snippets',{name:'SEED (temp)',code:SEED,scope:'front-end',active:true,priority:5});
  let sid2=null; try{sid2=JSON.parse(mk2).id;}catch(e){}
  execSync('sleep 4');
  try{ const r=execSync('curl -sk "https://dev.avesa.lt/?ps_seed=Seed25x"',{maxBuffer:5e6,timeout:60000}).toString();
    const a=r.indexOf('###SEED###'),b=r.indexOf('###END###'); o.seed=(a>=0&&b>a)?r.slice(a+10,b):r.slice(0,150); }catch(e){o.seed='ERR';}
  // NEtriname seed snippet dar - reikes screenshot. Bet issaugau sid2.
  o.sid2=sid2;

  // 3. Screenshot pet_id=30 dashboard
  const { chromium } = await import('playwright');
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 1000, height: 1500 }, ignoreHTTPSErrors: true });
  const page = await ctx.newPage();
  await page.goto('https://dev.avesa.lt/wp-login.php', { timeout: 30000 });
  await page.waitForSelector('#user_login', { timeout: 10000 });
  await page.fill('#user_login', U); await page.fill('#user_pass', P);
  await Promise.all([page.waitForNavigation({ waitUntil: 'networkidle' }), page.click('#wp-submit')]);
  await page.goto('https://dev.avesa.lt/my-account/augintinis/?pet=30', { waitUntil: 'networkidle', timeout: 40000 });
  await page.waitForTimeout(3000);
  await page.evaluate(() => { document.querySelectorAll('[id*="cmplz"],[class*="cmplz"]').forEach(function(e){if(e&&e.remove)e.remove();}); });
  await page.waitForTimeout(1500);
  o.snap = await page.evaluate(() => {
    var main=document.querySelector('.woocommerce-MyAccount-content')||document.body;
    return {
      hasNow: !!document.querySelector('.pspet-now'),
      nowTitle: document.querySelector('.pspet-now-t')?document.querySelector('.pspet-now-t').innerText.trim():null,
      feedingPlan: main.innerText.includes('Peržiūrėti planą'),
      shelf: main.innerText.includes('Maisto dar ~'),
      refillFb: main.innerText.includes('Dar liko'),
      repeat: main.innerText.includes('Įprasti pirkiniai')
    };
  });
  const buf=await page.screenshot({ fullPage:true }); fs.writeFileSync('/tmp/a2bc.png', buf); shots.push('a2bc');
  await browser.close();

  // 4. Isvalau seed duomenis + snippet
  const CLEAN=`<?php
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_clean']) || $_GET['ps_clean']!=='Clean25x') return;
  global $wpdb; $pf=$wpdb->prefix; $pid=30;
  $wpdb->update("{$pf}ps_pets", array('primary_product_id'=>null,'primary_product_name'=>null,'primary_product_package'=>null), array('id'=>$pid));
  $wpdb->query("DELETE FROM {$pf}ps_reminders WHERE pet_id=$pid AND reminder_label LIKE '%TEST%'");
  $rt=$pf.'ps_refill_tracking'; if($wpdb->get_var("SHOW TABLES LIKE '$rt'")){ $wpdb->query("DELETE FROM $rt WHERE pet_id=$pid"); }
  header('Content-Type: application/json'); echo '###CLEAN OK###'; exit;
});`;
  const mk3=wj('POST','code-snippets/v1/snippets',{name:'CLEAN (temp)',code:CLEAN,scope:'front-end',active:true,priority:5});
  let sid3=null; try{sid3=JSON.parse(mk3).id;}catch(e){}
  execSync('sleep 4');
  try{ const r=execSync('curl -sk "https://dev.avesa.lt/?ps_clean=Clean25x"',{maxBuffer:5e6,timeout:60000}).toString(); o.clean=r.includes('CLEAN OK')?'OK':r.slice(0,80); }catch(e){o.clean='ERR';}
  // trinu visus 3 temp snippet
  [sid2,sid3].forEach(function(id){ if(id!=null){ try{execSync('curl -sk '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+id+'"');}catch(e){} } });
}catch(e){ o.fatal=String(e).slice(0,300); }
for (const n of shots) { try { putB64(n+'.png', fs.readFileSync('/tmp/'+n+'.png').toString('base64')); } catch(e){} }
putB64('a2bc.json', Buffer.from(JSON.stringify(o)).toString('base64'));
console.log('done');
